// THE REAL FACES' GENERATED FILES — how the two bakes (`scripts/real-faces.mjs`
// for the heights, `scripts/real-hints.mjs` for the ski area's hints) write
// what they baked into the engine.
//
// ONE FILE A FACE, and an INDEX beside each kind: a face's heights are
// `engine/mapgen/real-faces/face-<id>.ts`, its hints
// `engine/mapgen/real-hints/hints-<id>.ts`, and nothing loads either until
// a map is raised on that face (`loadRealFace`, a dynamic import the
// bundler splits into a chunk of its own). The indexes are what is always
// in the bundle: every face's id, region and country, and which piste
// grades its real ski area signs — a few bytes a face, so the start card
// can list and filter a hundred faces without downloading one.
//
// A bake writes the faces it baked and leaves every other face's file as
// it is, so adding a face never moves one already shipped. Every file is
// laid out as the formatter would lay it, so `make fmt` leaves it alone.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const MAPGEN = join(root, "engine", "mapgen");
export const FACE_DIR = join(MAPGEN, "real-faces");
export const HINT_DIR = join(MAPGEN, "real-hints");
export const FACE_INDEX = join(MAPGEN, "real-faces-index.ts");
export const HINT_INDEX = join(MAPGEN, "real-hints-index.ts");

const DEM_NOTICE = [
  "// never edit by hand. The heights are off the Copernicus DEM GLO-30, ©",
  "// DLR e.V. 2010–2014 and © Airbus Defence and Space GmbH 2014–2018,",
  "// provided under COPERNICUS by the European Union and ESA",
  "// (docs/real-faces.md); `real-face.ts` reads them.",
];

const OSM_NOTICE = [
  "// never edit by hand. Read off OpenStreetMap, © OpenStreetMap",
  "// contributors, and available under the Open Database Licence 1.0, as",
  "// this derived database is (docs/real-faces.md); `real-hints.ts` reads it.",
];

function write(path, lines) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, lines.join("\n"));
}

/** One face's heights: `{ id, region, floor, data }`. */
export function writeFaceFile(b) {
  const path = join(FACE_DIR, `face-${b.id}.ts`);
  write(path, [
    "// SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0",
    "// GENERATED by `make real-faces ARGS=--write` (scripts/real-faces.mjs) —",
    ...DEM_NOTICE,
    "",
    'import type { FaceData } from "../real-faces-index.ts";',
    "",
    "export const FACE: FaceData = {",
    `  id: "${b.id}",`,
    `  region: "${b.region}",`,
    `  floor: ${b.floor},`,
    `  data: "${b.data}",`,
    "};",
    "",
  ]);
  return path;
}

/** The heights' index: every face of `faces` (`{ id, region, country }`),
 * the grid they are kept on, and the loader of each. */
export function writeFaceIndex(faces, grid) {
  write(FACE_INDEX, [
    "// SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0",
    "// GENERATED by `make real-faces ARGS=--write` (scripts/real-faces.mjs) —",
    "// never edit by hand. Every real face's id, region and country, and where",
    "// its heights are kept (`real-faces/face-<id>.ts`, loaded only when a map",
    "// is raised on it); `real-face.ts` reads it.",
    "",
    'import type { RegionId } from "./regions.ts";',
    "",
    "/** One face as baked: its region, the lowest height (m) and the grid. */",
    "export type FaceData = {",
    "  readonly id: string;",
    "  readonly region: RegionId;",
    "  readonly floor: number;",
    "  readonly data: string;",
    "};",
    "",
    "/** A face as the start card lists it: its region (R21) and the country it",
    " * lies in (ISO 3166-1 alpha-2). */",
    "export type FaceEntry = {",
    "  readonly id: string;",
    "  readonly region: RegionId;",
    "  readonly country: string;",
    "};",
    "",
    `/** The grid's samples a side and their spacing, m, and a height's step, m. */`,
    `export const FACE_GRID = { n: ${grid.n}, cell: ${grid.cell}, step: ${grid.step} } as const;`,
    "",
    "export const FACE_INDEX: readonly FaceEntry[] = [",
    ...faces.map((f) => `  { id: "${f.id}", region: "${f.region}", country: "${f.country}" },`),
    "];",
    "",
    "/** Each face's heights, fetched when a map is raised on it. */",
    "export const FACE_LOADERS: Readonly<Record<string, () => Promise<{ FACE: FaceData }>>> = {",
    ...faces.map((f) => `  "${f.id}": () => import("./real-faces/face-${f.id}.ts"),`),
    "};",
    "",
  ]);
}

/** One face's hints: `{ id, data }`. */
export function writeHintFile(b) {
  const path = join(HINT_DIR, `hints-${b.id}.ts`);
  write(path, [
    "// SPDX-License-Identifier: ODbL-1.0",
    "// GENERATED by `make real-hints ARGS=--write` (scripts/real-hints.mjs) —",
    ...OSM_NOTICE,
    "",
    'import type { HintData } from "../real-hints-index.ts";',
    "",
    "export const HINTS: HintData = {",
    `  id: "${b.id}",`,
    `  data: "${b.data}",`,
    "};",
    "",
  ]);
  return path;
}

/** The grades every face's index row already carries, read off the index
 * on disk, so a bake of a few faces keeps the rest. */
export function keptGrades() {
  if (!existsSync(HINT_INDEX)) return new Map();
  const text = readFileSync(HINT_INDEX, "utf8");
  const out = new Map();
  for (const m of text.matchAll(/^ {2}"([\w-]+)": \[([^\]]*)\],$/gm)) {
    out.set(
      m[1],
      [...m[2].matchAll(/"(\w+)"/g)].map((g) => g[1]),
    );
  }
  return out;
}

const GRADE_ORDER = ["green", "blue", "red", "black", "orange"];

/** The hints' index: for every face of `ids` that has hints, the piste
 * grades its real ski area signs (`grades`, id → grades), the grain the
 * hints are kept in, and the loader of each. */
export function writeHintIndex(ids, grades, grain) {
  const have = ids.filter((id) => grades.has(id));
  const sorted = (g) =>
    [...new Set(g)].sort((a, b) => GRADE_ORDER.indexOf(a) - GRADE_ORDER.indexOf(b));
  write(HINT_INDEX, [
    "// SPDX-License-Identifier: ODbL-1.0",
    "// GENERATED by `make real-hints ARGS=--write` (scripts/real-hints.mjs) —",
    "// never edit by hand. Which piste grades each real face's ski area signs,",
    "// read off OpenStreetMap, © OpenStreetMap contributors, under the Open",
    "// Database Licence 1.0 (docs/real-faces.md), and where each face's hints",
    "// are kept (`real-hints/hints-<id>.ts`, loaded only when a map is raised",
    "// on it); `real-hints.ts` reads it.",
    "",
    'import type { RunGrade } from "./grades.ts";',
    "",
    "/** One face's hints as baked: its id and the bytes, base64. */",
    "export type HintData = {",
    "  readonly id: string;",
    "  readonly data: string;",
    "};",
    "",
    "/** A lift's ends and a piste's bends are kept in steps of `coarse` m and",
    " * the piste's width at each bend in steps of `width` m (0 unknown), a",
    " * house's middle in steps of `fine` m and its size in steps of `size` m,",
    " * its bearing in `bearings` steps round half a turn. */",
    `export const HINT_GRAIN = { coarse: ${grain.coarse}, fine: ${grain.fine}, size: ${grain.size}, width: ${grain.width}, bearings: ${grain.bearings} } as const;`,
    "",
    "/** The grades of the real pistes on each face that has hints. */",
    "export const HINT_GRADES: Readonly<Record<string, readonly RunGrade[]>> = {",
    ...have.map(
      (id) =>
        `  "${id}": [${sorted(grades.get(id))
          .map((g) => `"${g}"`)
          .join(", ")}],`,
    ),
    "};",
    "",
    "/** Each face's hints, fetched when a map is raised on it. */",
    "export const HINT_LOADERS: Readonly<Record<string, () => Promise<{ HINTS: HintData }>>> = {",
    ...have.map((id) => `  "${id}": () => import("./real-hints/hints-${id}.ts"),`),
    "};",
    "",
  ]);
}
